#!/usr/bin/env python3
from pathlib import Path
from PIL import Image
import json,hashlib
from draw_relics import TIMES,OFFSETS,FLASH
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256((R/p).read_bytes()).hexdigest()
def build():
    path='Art/fx/relic_ring_8f.png';im=Image.open(R/path);frames=[];t=0
    for i,ms in enumerate(TIMES):
        frames.append({'index':i,'rect_px':[i*64,0,64,64],'start_ms':t,'duration_ms':ms,'bbox_local_px':im.crop((i*64,0,(i+1)*64,64)).getbbox(),'icon_offset_px':OFFSETS[i],'icon_warm_mix_weight':FLASH[i],'counter_plate_state':'active' if i in (2,3) else 'base'})
        t+=ms
    ring={'key':'relic_activation','path':path,'size_px':[512,64],'sha256':sha(path),'frame_count':8,'frame_size_px':[64,64],'anchor_px':[32,32],'anchor_normalized':[.5,.5],'transparent_icon_safe_rect_xywh':[15,15,34,34],'frames':frames,'total_ms':t,'loop':False,'last_frame_is_transparent':True,'post_action':'hide VFX only; restore icon local position and original color; preserve icon and authoritative count','sort':'behind all relic artwork; counter plates and runtime text above artwork; below tooltips','clip':'do not crop to the 36px icon-cell bounds; clamp/relocate at screen edges','retrigger':'same relic: coalesce multiple effects from one confirmed activation; if independent activation arrives while playing, restart once from frame 0 without stacking. Queue or rate-limit at caller; never count ring plays as gameplay charges.'}
    plates=[]
    for state in ['base','active']:
        p='Art/ui/relic_counter_plate'+('_active' if state=='active' else '')+'.png'
        plates.append({'key':'relic_counter_'+state,'path':p,'size_px':[24,14],'sha256':sha(p),'anchor_px':[12,7],'text_safe_rect_xywh':[4,3,16,8],'baked_text':False,'preview_mount_in_64px_cell_xy':[32,44],'runtime_text_color':'#bad2d9','suggested_runtime_text':'1-2 digits, centered; use 99+ with accessible full value when wider count cannot fit; do not auto-increment or derive from animation'})
    m={'schema_version':1,'bundle':'B5-relic-activation','date':'2026-11-08','branch':'codex/assets-b5-20261108','delivery_status':'asset bundle only; runtime integration not tested','production':{'pixel_format':'RGBA8','alpha_values':[0,255],'layout':'horizontal, left to right, zero-based','filter':'nearest','mipmaps':False,'blend_mode':'normal alpha','trim':False,'rotate_atlas_cells':False,'coordinate_system':'top-left image origin; rectangles x,y,width,height, bbox exclusive right/bottom','scale':'same logical-pixel scale as 32px relic art; uniform integer enlargement preferred; never force 64px texture into a 32px icon rectangle','palette':'palette.json','creation':'direct integer-grid pixel artwork; no image generation, no resampled source raster'},'animations':[ring],'ui_assets':plates,'icon_motion_contract':{'separate_from_texture':True,'units':'native relic icon pixels; y down','applies_to':'only the selected relic art, not hitbox, ring, counter or sibling icons','warm_mix_target_rgb_hex':'#dfc77f','return_to_baseline':True,'reduced_motion':'no icon shake; optionally show only plate active for 145ms, or a static subdued ring; no forced screen shake'},'caller_contract':{'confirmed_activation_required':True,'required_identity':'resolved relic ID and current visible icon position','event_name':'adapter-defined; no universal source event assumed','do_not_infer_from':['any HP change','any block gain','generic sourceUid without resolving its relic origin','counter decrement alone','hover','UI rebuild'], 'counter':'authoritative remaining/current value supplied by game; absent counter means hide plate; do not fabricate zero','offscreen_or_hidden_relic':'skip local overlay if no reliable icon anchor. Do not flash the +N inventory aggregate as if it were an identified relic.','audio':'none supplied; do not duplicate existing SE'},'previews':{'contactsheet':'previews/relics_contactsheet.png','native':'previews/relics_native.png','animation':'previews/relics_playback.png','timing':'previews/playback_timing.json','dummy_art_only':True}}
    (R/'manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':build()
